// El texto del aviso de privacidad, sin Flutter: lo usan la app y
// tool/aviso_html.dart, que genera web/privacidad.html.

/// Where any question or request about personal data goes.
const privacyForm = 'jaguarcode.org/#contacto';

const privacyUpdated = '26 de octubre de 2026';

/// The privacy notice, also published at /privacidad.html (generated by
/// tool/aviso_html.dart; a test checks it is up to date).
const privacySections = <(String, String)>[
  ('Quién es responsable', 'Jaguar Code es un proyecto educativo abierto de Panterino.'),
  (
    'Qué datos usamos',
    'Sin entrar en línea, nada sale de tu equipo. Si entras en línea, guardamos solo lo necesario para las '
        'clases y la comunidad: un alias, lo que publicas y tus entregas. A los profesores, además, su correo. '
        'No pedimos nombre real ni foto a los alumnos. Si pides acceso anticipado en la página, guardamos el '
        'correo que escribas.',
  ),
  (
    'Para qué',
    'Para que funcionen las clases y la comunidad. El correo del acceso anticipado es solo para darte entrada '
        'a la app y avisarte de novedades. No hay publicidad ni vendemos tus datos.',
  ),
  (
    'Menores de edad',
    'Si eres menor, pide a tu mamá, papá o tutor que lea este aviso antes de entrar en línea y no uses tu '
        'nombre completo como alias.',
  ),
  (
    'Tus derechos',
    'Puedes ver, corregir o borrar tus datos, u oponerte a que los usemos. Para borrar tu cuenta, elige '
        '"Borrar mi cuenta" en Jaguar. Para cualquier duda o solicitud, usa el formulario de $privacyForm y '
        'elige "Duda o solicitud sobre mis datos". Respondemos en un máximo de 20 días hábiles.',
  ),
  ('Cambios', 'Si este aviso cambia, lo publicamos en la app y en app.jaguarcode.org/privacidad con la fecha nueva.'),
];

String privacyHtml() {
  String escape(String text) => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  final sections = [
    for (final (title, body) in privacySections) '  <h2>${escape(title)}</h2>\n  <p>${escape(body)}</p>',
  ].join('\n');
  return '''<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Aviso de privacidad · Jaguar Code</title>
  <style>
    :root { color-scheme: light dark; --fondo: #fff8f0; --texto: #2b2118; --suave: #6b5d50; }
    @media (prefers-color-scheme: dark) { :root { --fondo: #1d1712; --texto: #f2e8dc; --suave: #b9aa9a; } }
    body { background: var(--fondo); color: var(--texto); font: 17px/1.55 system-ui, sans-serif; margin: 0; }
    main { max-width: 680px; margin: 0 auto; padding: 24px 16px 48px; }
    h1 { font-size: 1.6rem; margin-bottom: 4px; }
    h2 { font-size: 1.1rem; margin: 28px 0 6px; }
    .fecha { color: var(--suave); font-size: .9rem; }
  </style>
</head>
<body>
<main>
  <h1>Aviso de privacidad de Jaguar Code</h1>
  <p class="fecha">Última actualización: $privacyUpdated</p>
$sections
</main>
</body>
</html>
''';
}
